package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.DirectAccessVO;

class DirectAccessValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of direct access of tenant login provider")
  void test_direct_access_value_holder_assign_plain_value() {
    Object holder = new Object();
    DirectAccessValueHolder<Object> value = new DirectAccessValueHolder<>(holder);
    Assertions.assertSame(holder, value.directAccess(true), "Setters must return the holder");
    Assertions.assertTrue(value.getDirectAccessValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getDirectAccess().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.directAccessNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getDirectAccessValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of direct access of tenant login provider")
  void test_direct_access_value_holder_assign_value_object() {
    Object holder = new Object();
    DirectAccessValueHolder<Object> value = new DirectAccessValueHolder<>(holder);
    DirectAccessVO vo = DirectAccessVO.from(true);
    Assertions.assertFalse(value.getDirectAccessValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.directAccess(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getDirectAccessValue().orElseThrow());
    Assertions.assertSame(holder, value.directAccess(Optional.empty()));
    Assertions.assertFalse(value.getDirectAccessValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.directAccess(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDirectAccessValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of direct access of tenant login provider against the original")
  void test_direct_access_value_holder_read() {
    Object holder = new Object();
    DirectAccessValueHolder<Object> value = new DirectAccessValueHolder<>(holder);
    DirectAccessVO vo = DirectAccessVO.from(true);
    DirectAccessVO other = DirectAccessVO.from(true);
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getDirectAccessValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDirectAccess(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readDirectAccess(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.directAccess(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDirectAccess(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDirectAccess(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of direct access of tenant login provider")
  void test_direct_access_value_holder_unset() {
    Object holder = new Object();
    DirectAccessValueHolder<Object> value = new DirectAccessValueHolder<>(holder);
    DirectAccessVO vo = DirectAccessVO.from(true);
    value.directAccess(vo);
    Assertions.assertSame(holder, value.unsetDirectAccessIfMatches("directAccess_other"));
    Assertions.assertTrue(value.getDirectAccessValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetDirectAccessIfMatches("directAccess"));
    Assertions.assertFalse(value.getDirectAccessValue().isPresent(),
        "The field name must clear the value");
    value.directAccess(vo);
    Assertions.assertSame(holder, value.unsetDirectAccess());
    Assertions.assertFalse(value.getDirectAccessValue().isPresent(), "Unset must clear the value");
  }
}
